require"active_support/duration";require"active_support/core_ext/time/calculations";require"active_support/core_ext/time/acts_like";require"active_support/core_ext/date/calculations";require"active_support/core_ext/date/acts_like";class Numeric;def seconds;ActiveSupport::Duration.seconds(self);end;alias :second:seconds;def minutes;ActiveSupport::Duration.minutes(self);end;alias :minute:minutes;def hours;ActiveSupport::Duration.hours(self);end;alias :hour:hours;def days;ActiveSupport::Duration.days(self);end;alias :day:days;def weeks;ActiveSupport::Duration.weeks(self);end;alias :week:weeks;def fortnights;ActiveSupport::Duration.weeks(self*2);end;alias :fortnight:fortnights;def in_milliseconds;self*1000;end;end
